use vstd::prelude::*;

verus! {
    fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == m.len(),
            forall|i: nat| 0 <= i < m.len() ==> result[i] == m[(m.len() - 1 - i) as usize],
    {
        let n = m.len() as nat;
        let mut result: Vec<f32> = Vec::new();
        result.reserve(n as usize); // Reserve space for the result vector

        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                result.len() == i as usize,
                result.len() <= n as usize,
                forall|j: nat| 0 <= j < i ==> result[j] == m[(n - 1 - j) as usize],
            decreases n - i,
        {
            result.push(m[(n - 1 - i) as usize]);
            i = i + 1;
        }
        result
    }
}

